namespace KominkaHillside.Editor {public static partial class KH_WashSelectionEditor {
 [MenuItem(Menu+"44 - Verify Selection")]
 public static void VerifySelection(){Guard();var log=new StringBuilder();int bad=0;Action<bool,string> check=(ok,msg)=>{log.AppendLine((ok?"PASS ":"FAIL ")+msg);if(!ok)bad++;};var sels=UnityEngine.Object.FindObjectsOfType<KH_WashSelection>(true);check(sels.Length==4,"four selectors");check(sels.SelectMany(x=>x.slots).Distinct().Count()==28&&sels.SelectMany(x=>x.models).Distinct().Count()==68,"four stations own distinct pickups and visuals");var words=ReadWords();check(words.languages.Length==13&&words.languages.All(l=>l.words.Length==42),"13 languages / 42 words");foreach(var sel in sels){check(sel.slots.Length==7&&sel.models.Length==17,"slots and models "+sel.transform.parent.name);var back=UdonSharpEditorUtility.GetBackingUdonBehaviour(sel);check(back.SyncMethod==Networking.SyncType.Manual,"Manual selector");check(back.publicVariables.TryGetVariableValue<GameObject[]>("models",out var savedModels)&&savedModels.SequenceEqual(sel.models),"saved backing model references");object saved;back.publicVariables.TryGetVariableValue("slots",out saved);var savedSlots=saved as Array;check(savedSlots!=null&&savedSlots.Length==7&&Enumerable.Range(0,7).All(i=>{var x=savedSlots.GetValue(i) as UnityEngine.Object;return x==sel.slots[i]||x==UdonSharpEditorUtility.GetBackingUdonBehaviour(sel.slots[i]);}),"saved backing slot references ("+(saved!=null?saved.GetType().Name:"missing")+")");check(!PrefabUtility.IsPartOfPrefabInstance(sel),"selector is scene object");for(int i=0;i<13;i++){check(sel.models[i]!=null && sel.nozzleAnchors[i]!=null&&sel.gripAnchors[i]!=null,"anchors "+Names[i]);check(sel.colliderSizes[i].x>.02f&&sel.colliderSizes[i].y>.02f,"collider "+Names[i]);log.AppendLine("anchor "+Names[i]+" nozzle="+sel.nozzleAnchors[i].name+" grip="+sel.gripAnchors[i].name+" forward="+sel.slots[Slots[i]].transform.InverseTransformDirection(sel.nozzleAnchors[i].forward).ToString("F3"));}
 foreach(var t in sel.slots){check(UdonSharpEditorUtility.GetBackingUdonBehaviour(t).SyncMethod==Networking.SyncType.Continuous,"network-capable pickup backing");check(t.washes.Length==6&&t.finishTargets.Length==6&&t.selection==sel,"dog wiring "+t.name);check(t.state!=null&&UdonSharpEditorUtility.GetBackingUdonBehaviour(t.state).SyncMethod==Networking.SyncType.Manual,"Manual spray state");check(t.debugHeldOverride==0,"no debug override");}var board=sel.transform.parent.GetComponentInChildren<KH_WashSelectionBoard>(true);check(board!=null&&board.words.Length==546&&board.language!=null,"localized board");check(board.GetComponent<Canvas>()!=null&&board.GetComponent<VRC.SDK3.Components.VRCUiShape>()!=null&&board.GetComponent<BoxCollider>()!=null&&board.gameObject.layer==0,"canvas raycast surface");foreach(var a in sel.GetComponentsInChildren<AudioSource>(true).Concat(board.GetComponentsInChildren<AudioSource>(true)))check(KH_AudioSpatialEditor.Problem(a)==null,"finite spatial audio "+a.name);check(board.setPhotos.All(x=>x!=null)&&board.itemPhotos.All(x=>x!=null),"22 photos");foreach(var b in board.GetComponentsInChildren<Button>(true))check(b.onClick.GetPersistentEventCount()==1,"button "+b.name);}
 foreach(var f in UnityEngine.Object.FindObjectsOfType<KH_WashFinishFx>(true))check(UdonSharpEditorUtility.GetBackingUdonBehaviour(f).SyncMethod==Networking.SyncType.Manual,"network-capable cosmetic backing");var wash=UnityEngine.Object.FindObjectsOfType<KH_DogWash>(true)[0];var delta=(Vector4)typeof(KH_DogWash).GetMethod("ToolDelta",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(wash,new object[]{6,1f});check(delta.x==0&&delta.y==0&&delta.z<0,"dryer delta wetness only (C# shared body)");var first=sels[0];int oldTool=first.selectedTool,oldBath=first.selectedBath,oldRev=first.revision;bool oldDuck=first.duckOn;try{for(int i=0;i<17;i++){if(i<13)first.selectedTool=i;else if(i<16)first.selectedBath=i;else first.duckOn=true;first.revision++;first._Apply(false);check(first.models[i].activeSelf,"apply "+Names[i]);if(i<13)check(first.pickups.Where(p=>p.pickupable).Count()==1&&first.slots[Slots[i]].nozzle==first.nozzleAnchors[i],"one enabled pickup / nozzle "+Names[i]);}}finally{first.selectedTool=oldTool;first.selectedBath=oldBath;first.duckOn=oldDuck;first.revision=oldRev;first._Apply(false);}
 var board0=first.transform.parent.GetComponentInChildren<KH_WashSelectionBoard>(true);var lf=typeof(KH_WashSelectionBoard).GetField("_lang",BindingFlags.Instance|BindingFlags.NonPublic);int before=(int)lf.GetValue(board0);int overflow=0,missing=0;try{for(int l=0;l<words.languages.Length;l++){lf.SetValue(board0,l);for(int tab=0;tab<5;tab++){typeof(KH_WashSelectionBoard).GetMethod("_Tab"+tab).Invoke(board0,null);board0._Refresh();foreach(var t in board0.GetComponentsInChildren<TextMeshProUGUI>().Where(x=>x.gameObject.activeInHierarchy)){t.ForceMeshUpdate();var v=t.GetPreferredValues(t.text,t.rectTransform.rect.width,0);bool fail=t.isTextOverflowing; if(fail){overflow++;log.AppendLine("OVERFLOW "+words.languages[l].code+" "+t.name+" "+v+" rect "+t.rectTransform.sizeDelta+" pt "+t.fontSize);}foreach(char ch in t.text)if(!char.IsControl(ch)&&!t.font.HasCharacter(ch,true))missing++;}}}}finally{lf.SetValue(board0,before);board0._Tab0();}check(overflow==0&&missing==0,"rendered locale overflow="+overflow+" missing="+missing);log.AppendLine("NOT_TESTED: real two-client ownership, Quest sound/rendering, pickup hand alignment");Log("verify",bad==0?"PASS\n"+log:"FAIL="+bad+"\n"+log);if(bad>0)throw new Exception("Selection verification failures="+bad);}
 [MenuItem(Menu+"45 - Capture Selection")]
 public static void CaptureSelection(){Guard();var st=Calls()[0].transform.parent;var board=st.GetComponentInChildren<KH_WashSelectionBoard>(true);board._Tab0();var sel=board.selection;int tool=sel.selectedTool,bath=sel.selectedBath,rev=sel.revision;try{sel.selectedTool=0;sel.selectedBath=13;sel.revision++;sel._Apply(false);Canvas.ForceUpdateCanvases();Capture("board",board.transform.position+st.TransformDirection(new Vector3(0,0,-1.8f)),board.transform.position,.51f,1600,1200);Capture("station",st.TransformPoint(new Vector3(2.6f,2.0f,-3.8f)),st.TransformPoint(new Vector3(.1f,.8f,-.3f)),0,1600,1000);}finally{sel.selectedTool=tool;sel.selectedBath=bath;sel.revision=rev;sel._Apply(false);}}
 static void Capture(string name,Vector3 position,Vector3 look,float ortho,int width,int height){var go=new GameObject("WashEvidenceCamera");var cam=go.AddComponent<Camera>();var rt=new RenderTexture(width,height,24,RenderTextureFormat.ARGB32);var old=RenderTexture.active;try{cam.transform.position=position;cam.transform.rotation=Quaternion.LookRotation(look-position);cam.nearClipPlane=.03f;cam.farClipPlane=100;cam.fieldOfView=48;cam.orthographic=ortho>0;cam.orthographicSize=ortho;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tx=new Texture2D(width,height,TextureFormat.RGB24,false);tx.ReadPixels(new Rect(0,0,width,height),0,0);tx.Apply();Directory.CreateDirectory("artifacts/wash-listings/2026-10-08/evidence");File.WriteAllBytes("artifacts/wash-listings/2026-10-08/evidence/"+name+".png",tx.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tx);}finally{RenderTexture.active=old;cam.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
